; apx_instructions.asm -- APX new instructions (Phase 2, include/iset/apx.inc)
;
; Environment
;	Assembly-time only: nothing here is executed (no APX processor is public
;	yet). fasmg assembles each instruction inside VIRTUAL and compares the
;	bytes (reference: llvm-mc 23 with -mattr=+push2pop2,+ppx, generated by
;	tests/iset/_apx_diff.py; Intel APX spec 355828-009 3.1.3 where it
;	overrules LLVM); a mismatch stops assembly with 'encoding mismatch'. The
;	failure cases at the end are each assembled alone by _run.ps1
;	(-i"FAIL=n") and must stop with the quoted message.
;	By hand:  fasm2 apx_instructions.asm apx_instructions.bin
;
; What is new
;	push2/pop2 (EVEX map 4, ND=1, FF /6 and 8F /0 with Mod=3; first operand
;	in vvvv+V4, second in rm+B3+B4), their PPX forms push2p/pop2p (EVEX.W),
;	pushp/popp (REX2.W on 50+r/58+r, so REX2 even for rax-r15) and jmpabs
;	(REX2 A1 imm64). Failure modes this file guards against:
;	- the APX bits of the new EVEX layout: B4 in P0 bit 3 is not inverted,
;	  V4 in P2 bit 3 is; U (P1 bit 2) and ND are always 1;
;	- operand roles: push2 v, b pushes v first; pop2 v, b pops into v first;
;	- Intel 3.1.3.1.1: rsp in either operand, or pop2 with one register
;	  twice, is #UD. llvm-mc encodes all three; fasm2 refuses them;
;	- pushp/popp must not fall back to REX or no prefix: the hint is REX2.W;
;	- push/pop/pushp/popp register lists take r16-r31 (x86.compact).
;
; FAIL 1: 'APX_F or higher required'
; FAIL 2: 'APX_F or higher required'
; FAIL 3: 'APX_F or higher required'
; FAIL 4: 'APX_F or higher required'
; FAIL 5: 'bits64 or higher required'
; FAIL 6: 'rsp not allowed'
; FAIL 7: 'rsp not allowed'
; FAIL 8: 'pop2 registers must differ'
; FAIL 9: 'invalid combination of operands'
; FAIL 10: 'invalid combination of operands'
; FAIL 11: 'invalid operand'
; FAIL 12: 'invalid operand'
; FAIL 13: 'invalid operand'

macro expect bytes*, line&
	local n, got, k, want
	virtual at 0
		line
		n = $
		load got:n from 0
	end virtual
	virtual at 0
		db bytes
		k = $
		load want:k from 0
	end virtual
	if n <> k | got <> want
		display 'FAIL: ', `line, 13, 10
		err 'encoding mismatch'
	end if
end macro

use64
use everything

if ~ defined FAIL

	; push2/pop2: v = first operand (vvvv, V4 inverted in P2), b = second (rm, B3, B4)
	expect <62h,0F4h,7Ch,18h,0FFh,0F3h>, push2 rax, rbx
	expect <62h,0F4h,7Ch,10h,0FFh,0F3h>, push2 r16, rbx
	expect <62h,0FCh,64h,18h,0FFh,0F0h>, push2 rbx, r16
	expect <62h,0DCh,04h,10h,0FFh,0F7h>, push2 r31, r31
	expect <62h,0D4h,3Ch,18h,0FFh,0F7h>, push2 r8, r15
	expect <62h,0D4h,3Ch,10h,0FFh,0F1h>, push2 r24, r9
	expect <62h,0DCh,04h,18h,0FFh,0F1h>, push2 r15, r25
	expect <62h,0F4h,7Ch,18h,0FFh,0F0h>, push2 rax, rax	; only pop2 needs two registers
	expect <62h,0F4h,64h,18h,8Fh,0C0h>, pop2 rbx, rax
	expect <62h,0F4h,7Ch,10h,8Fh,0C3h>, pop2 r16, rbx
	expect <62h,0FCh,64h,18h,8Fh,0C0h>, pop2 rbx, r16
	expect <62h,0DCh,04h,10h,8Fh,0C6h>, pop2 r31, r30

	; PPX: EVEX.W
	expect <62h,0F4h,0FCh,18h,0FFh,0F3h>, push2p rax, rbx
	expect <62h,0D4h,0E4h,18h,0FFh,0F0h>, push2p rbx, r8
	expect <62h,0DCh,0FCh,10h,0FFh,0F7h>, push2p r16, r31
	expect <62h,0F4h,0E4h,18h,8Fh,0C0h>, pop2p rbx, rax
	expect <62h,0FCh,84h,10h,8Fh,0C0h>, pop2p r31, r16

	; PPX: REX2.W, also for rax-r15
	expect <0D5h,08h,50h>, pushp rax
	expect <0D5h,08h,53h>, pushp rbx
	expect <0D5h,09h,50h>, pushp r8
	expect <0D5h,18h,50h>, pushp r16
	expect <0D5h,18h,57h>, pushp r23
	expect <0D5h,19h,57h>, pushp r31
	expect <0D5h,08h,58h>, popp rax
	expect <0D5h,08h,5Bh>, popp rbx
	expect <0D5h,09h,5Fh>, popp r15
	expect <0D5h,18h,58h>, popp r16
	expect <0D5h,19h,5Fh>, popp r31

	; register lists (fasm2 syntax; the bytes are the single forms in order)
	expect <50h,0D5h,10h,50h,0D5h,11h,57h>, push rax r16 r31
	expect <0D5h,11h,5Fh,0D5h,10h,58h,58h>, pop r31 r16 rax
	expect <66h,0D5h,10h,50h,66h,0D5h,10h,51h>, pushw r16w r17w
	expect <0D5h,08h,50h,0D5h,18h,50h>, pushp rax r16
	expect <0D5h,18h,58h,0D5h,08h,58h>, popp r16 rax

	; jmpabs
	expect <0D5h,00h,0A1h,89h,67h,45h,23h,01h,00h,00h,00h>, jmpabs 123456789h
	expect <0D5h,00h,0A1h,00h,00h,00h,00h,00h,00h,00h,00h>, jmpabs 0
	expect <0D5h,00h,0A1h,0FFh,0FFh,0FFh,0FFh,0FFh,0FFh,0FFh,0FFh>, jmpabs 0FFFFFFFFFFFFFFFFh
	expect <0D5h,00h,0A1h,0FFh,0FFh,0FFh,0FFh,0FFh,0FFh,0FFh,0FFh>, jmpabs -1

else if FAIL = 1	; every new instruction needs APX_F
	use i386, x64
	push2 rax, rbx

else if FAIL = 2
	use i386, x64
	pushp rax

else if FAIL = 3
	use i386, x64
	jmpabs 0

else if FAIL = 4	; a register list with r16 too
	use i386, x64
	push rax r16

else if FAIL = 5	; 64-bit code only
	use32
	pop2 eax, ebx

else if FAIL = 6	; #UD: rsp (llvm-mc encodes it)
	push2 rsp, rax

else if FAIL = 7
	pop2 rax, rsp

else if FAIL = 8	; #UD: pop2 into one register twice (llvm-mc encodes it)
	pop2 rax, rax

else if FAIL = 9	; 64-bit registers only
	push2 eax, ebx

else if FAIL = 10	; Mod=3: no memory operand
	push2 rax, [rbx]

else if FAIL = 11	; the PPX hint implies 64-bit
	pushp eax

else if FAIL = 12
	popp qword [rax]

else if FAIL = 13	; an immediate target only
	jmpabs rax

end if
